 static class JavaApprovals {
  sealed class Jar {public string id,name,author,workshopId,path,sha256,warning;public bool? decision;}
  sealed class Snapshot {public string File,Stamp,DefaultHome;public bool Preflight;public int RemainingDirectories=4096;public long RemainingBytes=134217728;public byte[] Original;public Dictionary<string,object> Data;public List<Dictionary<string,object>> Entries;public List<Jar> Jars=new List<Jar>();public List<string> Evidence=new List<string>();}
  internal sealed class PreflightApprovals {public bool supported;public int pending,denied;}
  static readonly string[] Managed={"Viewpoint","ShootToThrillMultiplayer","LaoYuTranslationJava","OrangeShootPresentation"};
  static readonly ulong[] Items={3809306528,3813032735,3810637496};
  static JavaScriptSerializer Json(){return new JavaScriptSerializer{MaxJsonLength=2097152,RecursionLimit=64};}
  static string Hash(byte[] data){using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(data)).Replace("-","").ToLowerInvariant();}
  static string HashFile(string file,Snapshot snapshot=null){using(var sha=SHA256.Create())using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read)){if(snapshot!=null&&snapshot.Preflight){if(input.Length>snapshot.RemainingBytes)throw new Exception("Java 预检文件超出读取预算。");snapshot.RemainingBytes-=input.Length;}return BitConverter.ToString(sha.ComputeHash(input)).Replace("-","").ToLowerInvariant();}}
  static string Full(string path){if(string.IsNullOrWhiteSpace(path)||!Path.IsPathRooted(path))throw new Exception("Java 配置路径不是明确的绝对路径。");string result=Path.GetFullPath(path);LauncherMaintenance.NoReparse(result);return result;}
  static SteamLaunchOptionsSnapshot Guard(Engine e){e.Guard();if(LaunchProfiles.Pending(e))throw new Exception("启动配置尚未恢复，请退出游戏并完成恢复后授权。");if(File.Exists(Path.Combine(e.Data,"workshop-rebuild.pending")))throw new Exception("工坊维护未完成，请完成维护后授权。");var options=e.ReadSteamOptions();options.RequireReadable();if(options.HasField&&BuddyLaunchArguments.HasAuthorizationOverride(options.LaunchOptions))throw new Exception("当前游戏 Steam 启动选项含额外 Java 目录或代理覆盖，无法确认授权目录；请清理后再授权。");return options;}
  static byte[] Read(Snapshot s,string file,int max=2097152){LauncherMaintenance.NoReparse(file);if(File.Exists(file)){long size=new FileInfo(file).Length;if(size>max||s.Preflight&&size>s.RemainingBytes)throw new Exception("Java 授权检查文件异常过大。");if(s.Preflight)s.RemainingBytes-=size;}byte[] b=File.Exists(file)?File.ReadAllBytes(file):null;if(b!=null&&b.Length>max)throw new Exception("Java 授权检查文件异常过大。");s.Evidence.Add(Path.GetFullPath(file)+"="+(b==null?"missing":Hash(b)));return b;}
  static string Text(byte[] b){return b==null?"":new UTF8Encoding(false,true).GetString(b).TrimStart('\uFEFF');}
  static string[] Args(Dictionary<string,object> node){object value;if(!node.TryGetValue("vmArgs",out value)||!(value is IEnumerable)||value is string)throw new Exception("无法识别 Java 启动参数。");var list=((IEnumerable)value).Cast<object>().ToArray();if(list.Any(x=>!(x is string)))throw new Exception("Java 启动参数必须是字符串。");return list.Cast<string>().ToArray();}
  static IEnumerable<Dictionary<string,object>> Branches(Dictionary<string,object> node){foreach(var pair in node){var d=pair.Value as Dictionary<string,object>;if(d==null)continue;if(d.ContainsKey("vmArgs"))yield return d;foreach(var sub in Branches(d))yield return sub;}}
  static string JavaHome(Engine e,Snapshot s){if(s.DefaultHome!=null)return s.DefaultHome;if(s.Preflight)throw new Exception("只读预检不启动 Java 探测默认授权目录，请在 Java 授权页核对。");string java=Full(Path.Combine(e.Game,"jre64/bin/java.exe"));if(!File.Exists(java))throw new Exception("游戏自带 Java 缺失，无法确认默认授权目录。");var start=new ProcessStartInfo(java,"-XshowSettings:properties -version"){UseShellExecute=false,CreateNoWindow=true,WorkingDirectory=e.Game,RedirectStandardError=true,RedirectStandardOutput=true};using(var p=Process.Start(start)){var output=p.StandardError.ReadToEndAsync();var unused=p.StandardOutput.ReadToEndAsync();if(!p.WaitForExit(5000)){p.Kill();throw new Exception("Java 用户目录检查超时。");}System.Threading.Tasks.Task.WaitAll(output,unused);var matches=Regex.Matches(output.Result,@"(?m)^\s*user\.home\s*=\s*(.+)\s*$");if(p.ExitCode!=0||matches.Count!=1)throw new Exception("无法读取游戏 Java 的用户目录。");s.DefaultHome=Full(matches[0].Groups[1].Value.Trim());s.Evidence.Add("javaHome="+s.DefaultHome);return s.DefaultHome;}}
  static string DirectoryFor(Engine e,Snapshot s,string[] args){
   var homes=new List<string>();var dirs=new List<string>();int buddy=0;
   foreach(string arg in args){if(arg.StartsWith("-agentpath:",StringComparison.OrdinalIgnoreCase))throw new Exception("存在未核实的原生代理路径，无法确认 Java 授权目录。");if(arg.StartsWith("-Duser.home=",StringComparison.Ordinal))homes.Add(Full(arg.Substring(12)));if(arg.StartsWith("-D",StringComparison.Ordinal)&&arg.IndexOf("config_dir",StringComparison.OrdinalIgnoreCase)>=0)throw new Exception("不支持通过系统属性前缀覆盖 Buddy 配置目录。");string options=null;
    if(arg.StartsWith("-agentlib:zbNative",StringComparison.Ordinal)){string rest=arg.Substring(18);if(rest!=""&&!rest.StartsWith("="))throw new Exception("无法识别 Buddy 原生代理参数。");options=rest.TrimStart('=');buddy++;}
    else if(arg.StartsWith("-javaagent:",StringComparison.Ordinal)){var parts=arg.Substring(11).Split(new[]{'='},2);if(!string.Equals(Path.GetFileName(parts[0]),"ZombieBuddy.jar",StringComparison.OrdinalIgnoreCase))throw new Exception("存在其他 Java 代理，无法确认授权目录。");buddy++;options=parts.Length==2?parts[1]:"";}
    if(options!=null)foreach(string opt in options.Split(',')){var bits=opt.Split(new[]{'='},2);if(bits[0].Trim()=="prefix")throw new Exception("存在 Buddy 属性前缀覆盖，无法确认授权目录。");if(bits[0].Trim()=="config_dir")dirs.Add(Full(bits.Length==2?bits[1].Trim():""));else if(opt.Length!=0)throw new Exception("Buddy 自定义选项不明确，无法确认授权目录。");}
   }
   if(buddy!=1)throw new Exception("需要一个明确的 Buddy 启动代理。");if(homes.Distinct(StringComparer.OrdinalIgnoreCase).Count()>1||dirs.Distinct(StringComparer.OrdinalIgnoreCase).Count()>1)throw new Exception("Java 授权目录覆盖存在冲突。");return dirs.Count>0?dirs[0]:Path.Combine(homes.Count>0?homes[0]:JavaHome(e,s),".zombie_buddy");
  }
  static string ConfigDirectory(Engine e,Snapshot s){foreach(string name in new[]{"JAVA_TOOL_OPTIONS","_JAVA_OPTIONS","JDK_JAVA_OPTIONS"})if(!string.IsNullOrWhiteSpace(Environment.GetEnvironmentVariable(name)))throw new Exception("环境变量覆盖 Java 参数，无法确认授权目录。");var root=Json().Deserialize<Dictionary<string,object>>(Text(Read(s,e.Config)));if(root==null)throw new Exception("Java 启动配置无效。");string[] basic=Args(root);var paths=new List<string>{DirectoryFor(e,s,basic)};foreach(var branch in Branches(root))paths.Add(DirectoryFor(e,s,basic.Concat(Args(branch)).ToArray()));if(paths.Distinct(StringComparer.OrdinalIgnoreCase).Count()!=1)throw new Exception("Windows 分支的 Java 授权目录或代理不一致。");return Full(paths[0]);}
  static Dictionary<string,string> Metadata(Snapshot s,string file){string text=Text(Read(s,file,262144));var d=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string line in text.Split('\n')){int at=line.IndexOf('=');if(at<0)continue;string key=line.Substring(0,at).Trim(),value=line.Substring(at+1).Trim();if(new[]{"id","name","javaJarFile","javaPkgName","author"}.Contains(key,StringComparer.OrdinalIgnoreCase)){if(d.ContainsKey(key)&&d[key]!=value)throw new Exception("Java 模组元数据有冲突字段。");d[key]=value;}}return d;}
  static string[] Directories(Snapshot s,string root){LauncherMaintenance.NoReparse(root);if(!Directory.Exists(root))return new string[0];var dirs=Directory.EnumerateDirectories(root).Take((s.Preflight?s.RemainingDirectories:4096)+1).ToArray();if(dirs.Length>(s.Preflight?s.RemainingDirectories:4096))throw new Exception("模组目录过多，无法安全核对。");if(s.Preflight)s.RemainingDirectories-=dirs.Length;return dirs;}
  static void Inventory(Engine e,Snapshot s,HashSet<string> folders){
   var roots=new HashSet<string>(StringComparer.OrdinalIgnoreCase){Path.Combine(e.User,"mods")};
   foreach(ulong id in Items){roots.Add(Path.Combine(InstallWorkflow.Source(e,id),"mods"));roots.Add(Path.Combine(e.Workshop,id.ToString(),"mods"));}if(e.ViewSource!=null)roots.Add(Path.Combine(e.ViewSource,"mods"));
   string record=Path.Combine(e.Data,"workshop-paths.json");byte[] bytes=Read(s,record);if(bytes!=null){var mapped=Json().Deserialize<Dictionary<string,string>>(Text(bytes));if(mapped==null)throw new Exception("工坊路径记录无效。");foreach(var path in mapped.Values)roots.Add(Path.Combine(Full(path),"mods"));}
   LauncherMaintenance.NoReparse(e.Workshop);if(Directory.Exists(e.Workshop))foreach(string item in Directories(s,e.Workshop)){LauncherMaintenance.NoReparse(item);roots.Add(Path.Combine(item,"mods"));}
   foreach(string root in roots.OrderBy(x=>x,StringComparer.OrdinalIgnoreCase)){LauncherMaintenance.NoReparse(root);string[] dirs=Directories(s,root);if(dirs.Length>4096)throw new Exception("模组目录过多，无法安全核对。");s.Evidence.Add(Path.GetFullPath(root)+"="+string.Join("|",dirs.OrderBy(x=>x,StringComparer.OrdinalIgnoreCase)));foreach(string dir in dirs){LauncherMaintenance.NoReparse(dir);folders.Add(Path.GetFullPath(dir));}}
  }
  // Build only identity matches for this capture. Metadata and filesystem state
  // are read again by every later capture and selected-source validation below.
  static Dictionary<string,List<string>> Sources(Snapshot s,HashSet<string> folders){var sources=new Dictionary<string,List<string>>(StringComparer.Ordinal);foreach(string folder in folders){var identities=new HashSet<string>(StringComparer.Ordinal);foreach(string part in new[]{"","common","42"}){string id;var info=Metadata(s,Path.Combine(folder,part,"mod.info"));if(info.TryGetValue("id",out id))identities.Add(id);}foreach(string id in identities){List<string> matches;if(!sources.TryGetValue(id,out matches)){matches=new List<string>();sources[id]=matches;}matches.Add(folder);}}return sources;}
  static void LoadStore(Snapshot s){s.Original=Read(s,s.File);if(s.Original==null){s.Data=new Dictionary<string,object>{{"formatVersion",2},{"mods",new object[0]}};s.Entries=new List<Dictionary<string,object>>();return;}
   s.Data=Json().Deserialize<Dictionary<string,object>>(Text(s.Original));object version,mods;if(s.Data==null||!s.Data.TryGetValue("formatVersion",out version)||!(version is int)||((int)version)!=2||!s.Data.TryGetValue("mods",out mods)||!(mods is IList))throw new Exception("授权文件不是受支持的 v2 格式；未改动。");s.Entries=new List<Dictionary<string,object>>();var hashes=new Dictionary<string,bool>();
   foreach(object item in (IList)mods){var row=item as Dictionary<string,object>;object h,d;if(row==null||!row.TryGetValue("jar_hash",out h)||!(h is string)||!Regex.IsMatch((string)h,@"^[a-f0-9]{64}$")||!row.TryGetValue("decision",out d)||!(d is bool))throw new Exception("授权文件包含无效记录；未改动。");bool prev;if(hashes.TryGetValue((string)h,out prev)&&prev!=(bool)d)throw new Exception("授权文件包含同一 SHA-256 的冲突决定；未改动。");hashes[(string)h]=(bool)d;s.Entries.Add(row);}
  }
  static Snapshot Capture(Engine e,bool preflight=false){
   var options=Guard(e);var s=new Snapshot{Preflight=preflight};s.Evidence.Add("steam="+options.ScopedStamp);s.File=Path.Combine(ConfigDirectory(e,s),"mod_approvals.json");LauncherMaintenance.NoReparse(s.File);LoadStore(s);string text=Text(Read(s,e.Mods));var blocks=Regex.Matches(text,@"\bmods\s*\{(?<body>[^}]*)\}");if(blocks.Count!=1)throw new Exception("无法识别当前启用模组列表。");var enabled=Regex.Matches(blocks[0].Groups["body"].Value,@"(?m)^\s*mod\s*=\s*([^,\r\n]+)\s*,").Cast<Match>().Select(m=>m.Groups[1].Value.Trim()).Where(Managed.Contains).Distinct().ToArray();var folders=new HashSet<string>(StringComparer.OrdinalIgnoreCase);Inventory(e,s,folders);var sources=enabled.Length>0?Sources(s,folders):null;
   foreach(string id in enabled){List<string> matches;if(!sources.TryGetValue(id,out matches)||matches.Count!=1)throw new Exception("模组 "+id+" 来源缺失或重复，无法确认游戏将加载的文件。");string chosen=matches[0];string expected=id==Managed[3]?Path.Combine(e.User,"mods",id):Path.Combine(id==Managed[0]?(e.ViewSource??InstallWorkflow.Source(e,Items[0])):InstallWorkflow.Source(e,id==Managed[1]?Items[1]:Items[2]),"mods",id);if(!string.Equals(Path.GetFullPath(chosen),Path.GetFullPath(expected),StringComparison.OrdinalIgnoreCase))throw new Exception("模组 "+id+" 来自工具未管理的覆盖目录。");
    foreach(string part in new[]{"","common","42"}){string declared;var info=Metadata(s,Path.Combine(chosen,part,"mod.info"));if(info.TryGetValue("id",out declared)&&declared!=id)throw new Exception("Java 模组 common / 42 身份冲突。");}
    Dictionary<string,string> metadata=null;string jar=null;foreach(var candidate in new[]{new[]{"42","42"},new[]{"common","common"},new[]{"common","42"}}){var info=Metadata(s,Path.Combine(chosen,candidate[0],"mod.info"));string relative,pkg;if(!info.TryGetValue("javaJarFile",out relative)||!info.TryGetValue("javaPkgName",out pkg)||string.IsNullOrWhiteSpace(pkg))continue;if(Path.IsPathRooted(relative)||relative.Split(new[]{'/','\\'}).Any(x=>x==".."))throw new Exception("Java 模组路径越界。");string p=Path.GetFullPath(Path.Combine(chosen,candidate[1],relative));if(!p.StartsWith(Path.GetFullPath(chosen)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase)||!p.EndsWith(".jar",StringComparison.Ordinal)||relative.Replace('\\','/').Contains("media/java/server/"))throw new Exception("Java 模组文件路径无效。");LauncherMaintenance.NoReparse(p);if(File.Exists(p)){jar=p;metadata=info;break;}}
    if(jar==null)throw new Exception("模组 "+id+" 当前版本 Java 文件缺失。");string hash=HashFile(jar,s);s.Evidence.Add(jar+"="+hash);var entry=s.Entries.LastOrDefault(x=>(string)x["jar_hash"]==hash);string name,author;metadata.TryGetValue("name",out name);metadata.TryGetValue("author",out author);s.Jars.Add(new Jar{id=id,name=name??id,author=string.IsNullOrEmpty(author)?"签名作者未核验":author+"（元数据，未核验签名）",workshopId=id==Managed[3]?"":Items[Array.IndexOf(Managed,id)].ToString(),path=jar,sha256=hash,decision=entry==null?(bool?)null:(bool)entry["decision"],warning="Java 代码可访问本机文件。此选择仅适用于当前文件；官方签名、封禁、版本及服务器校验仍由游戏执行。"});
   }
   foreach(var addon in ViewpointAddons.All.Where(a=>ViewpointAddons.Enabled(e,a))){var f=ViewpointAddons.Find(e,addon);if(f.Jar==null)continue;if(sources==null)sources=Sources(s,folders);List<string> matches;if(sources.TryGetValue(addon.Id,out matches)&&matches.Any(folder=>!string.Equals(folder,f.Folder,StringComparison.OrdinalIgnoreCase)))throw new Exception("扩展来源重复，无法确认 Java 授权目标："+addon.Title);var metadata=Metadata(s,f.Info);if(f.Info!=Path.Combine(f.Folder,"common","mod.info"))foreach(var pair in Metadata(s,Path.Combine(f.Folder,"common","mod.info")))if(!metadata.ContainsKey(pair.Key))metadata[pair.Key]=pair.Value;string pkg;if(!metadata.TryGetValue("javaPkgName",out pkg)||string.IsNullOrWhiteSpace(pkg))throw new Exception("Java 包身份缺失："+addon.Title);string hash=HashFile(f.Jar,s);s.Evidence.Add(f.Jar+"="+hash);var entry=s.Entries.LastOrDefault(x=>(string)x["jar_hash"]==hash);string author;metadata.TryGetValue("author",out author);s.Jars.Add(new Jar{id=addon.Id,name=addon.Title,author=string.IsNullOrEmpty(author)?"作者声明未提供":author+"（元数据，未核验签名）",workshopId=addon.Item.ToString(),path=f.Jar,sha256=hash,decision=entry==null?(bool?)null:(bool)entry["decision"],warning="可选 Java 扩展；逐个文件确认，更新后需重新授权。"});}
   s.Evidence.Add("target="+s.File);s.Stamp=Hash(Encoding.UTF8.GetBytes(string.Join("\n",s.Evidence)));return s;
  }
  static object View(Snapshot s){return new{supported=true,stamp=s.Stamp,jars=s.Jars,warnings=new[]{"仅管理当前启用的工具组件；存档或服务器新增 Java 模组仍会由游戏询问。","作者信任未修改；已有作者信任可能影响游戏中的实际允许状态。"}};}
  public static object List(Engine e){try{return View(Capture(e));}catch(Exception ex){return new{supported=false,stamp="",jars=new object[0],warnings=new[]{ex.Message}};}}
  internal static PreflightApprovals CheckForPreflight(Engine e){try{var snapshot=Capture(e,true);return new PreflightApprovals{supported=true,pending=snapshot.Jars.Count(j=>!j.decision.HasValue),denied=snapshot.Jars.Count(j=>j.decision==false)};}catch{return new PreflightApprovals{supported=false};}}
  static bool Same(string file,byte[] original){LauncherMaintenance.NoReparse(file);return original==null?!File.Exists(file):File.Exists(file)&&File.ReadAllBytes(file).SequenceEqual(original);}
  static void PrivateWrite(string path,byte[] bytes){var acl=new FileSecurity();acl.SetAccessRuleProtection(true,false);acl.AddAccessRule(new FileSystemAccessRule(WindowsIdentity.GetCurrent().User,FileSystemRights.FullControl,AccessControlType.Allow));using(var output=new FileStream(path,FileMode.CreateNew,FileSystemRights.Write,FileShare.None,4096,FileOptions.WriteThrough,acl)){output.Write(bytes,0,bytes.Length);output.Flush(true);}}
  public static object Save(Engine e,string stamp,string hash,bool decision){
   if(!Regex.IsMatch(stamp??"",@"^[a-f0-9]{64}$")||!Regex.IsMatch(hash??"",@"^[a-f0-9]{64}$"))throw new Exception("授权快照无效，请刷新并重新核对。");Guard(e);var first=Capture(e);string name="Local\\OrangeJavaApprovals-"+Hash(Encoding.UTF8.GetBytes(first.File.ToUpperInvariant()));string launch="Local\\OrangeLaunch-"+DlssInstaller.Hash(Encoding.UTF8.GetBytes(Path.GetFullPath(e.User).ToUpperInvariant()));using(var lm=new Mutex(false,launch))using(var mutex=new Mutex(false,name)){bool a=false,b=false;try{try{a=lm.WaitOne(0);}catch(AbandonedMutexException){a=true;}if(!a)throw new Exception("另一启动器正在准备游戏。");try{b=mutex.WaitOne(0);}catch(AbandonedMutexException){b=true;}if(!b)throw new Exception("另一启动器正在保存 Java 授权。");var current=Capture(e);if(current.Stamp!=stamp||current.File!=first.File)throw new Exception("文件或配置已改变，请刷新并重新核对授权。");var jar=current.Jars.FirstOrDefault(x=>x.sha256==hash);if(jar==null)throw new Exception("所选 SHA-256 不在当前启用的工具组件中。");
    var selected=current.Entries.Where(x=>(string)x["jar_hash"]==hash).ToArray();if(selected.Length==0){var row=new Dictionary<string,object>{{"id",jar.id},{"jar_hash",hash},{"decision",decision}};if(jar.workshopId!="")row["workshop_id"]=long.Parse(jar.workshopId);current.Entries.Add(row);}else foreach(var row in selected)row["decision"]=decision;current.Data["mods"]=current.Entries;byte[] next=new UTF8Encoding(false).GetBytes(Json().Serialize(current.Data));string directory=Path.GetDirectoryName(current.File);LauncherMaintenance.NoReparse(directory);Directory.CreateDirectory(directory);string temp=current.File+".orange-"+Guid.NewGuid().ToString("N")+".tmp";string backup=current.File+".orange-backup-"+Guid.NewGuid().ToString("N");
    var locks=new List<FileStream>();try{foreach(string path in current.Jars.Where(x=>x.sha256==hash).Select(x=>x.path).Distinct())locks.Add(new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read));if(Capture(e).Stamp!=stamp)throw new Exception("授权核对期间文件已改变。");PrivateWrite(temp,next);Guard(e);if(!Same(current.File,current.Original))throw new Exception("授权文件已被其他程序修改，请刷新。");if(current.Original!=null)PrivateWrite(backup,current.Original);if(!Same(current.File,current.Original))throw new Exception("授权文件在保存前发生改变，请刷新。");if(current.Original==null)File.Move(temp,current.File);else File.Replace(temp,current.File,null);if(!File.ReadAllBytes(current.File).SequenceEqual(next))throw new Exception("授权写入后的核对失败，请刷新查看。");}finally{foreach(var file in locks)file.Dispose();if(File.Exists(temp))File.Delete(temp);}
    return List(e);
   }finally{if(b)mutex.ReleaseMutex();if(a)lm.ReleaseMutex();}}
  }
 }
